import base64, os

OUT = "/Users/goons/Downloads/yuu-agent/Product/NS-test/public/icons/drawer"
os.makedirs(OUT, exist_ok=True)

icons = {
    "drawer-zhao-hui.png": "",
    "drawer-bell.png": "",
    "drawer-calendar.png": "",
    "drawer-sales.png": "",
    "drawer-detail.png": "",
    "drawer-to-sign.png": "",
    "drawer-question.png": "",
    "drawer-apps.png": "",
    "drawer-move.png": "",
}

for filename, b64 in icons.items():
    path = os.path.join(OUT, filename)
    with open(path, "wb") as f:
        f.write(base64.b64decode(b64))
    print(f"✓ {filename}")

print("完成")
